import numpy as np, itertools
def read(p):
    L=open(p).read().split('\n'); n=int(L[0]); els=[]; xyz=[]
    for l in L[2:2+n]:
        q=l.split(); els.append(q[0]); xyz.append([float(x) for x in q[1:4]])
    return els, np.array(xyz)
els,xyz = read('opt_a.xyz')
cov = {'H':0.31,'C':0.76,'N':0.71,'Ga':1.22,'Ni':1.24}
# connectivity check: single fragment?
n=len(els)
adj=[[] for _ in range(n)]
for i,j in itertools.combinations(range(n),2):
    d=np.linalg.norm(xyz[i]-xyz[j])
    if d < cov[els[i]]+cov[els[j]]+0.45:
        adj[i].append(j); adj[j].append(i)
seen=set(); stack=[0]
while stack:
    k=stack.pop()
    if k in seen: continue
    seen.add(k); stack.extend(adj[k])
print('fragments connected:', len(seen)==n, len(seen), n)
# min nonbonded contact
bad=[]
for i,j in itertools.combinations(range(n),2):
    d=np.linalg.norm(xyz[i]-xyz[j])
    if j not in adj[i] and d < 1.6: bad.append((i,j,els[i],els[j],round(d,2)))
print('tight nonbonded:', bad[:10])
